svg.metadata:
{
  "source": "영도-고립된낙원 캐릭터 카드.pdf",
  "source_page_size_pt": [
    1350,
    810
  ],
  "viewBox": [
    0,
    0,
    1350,
    810
  ],
  "aspect_ratio": "5:3",
  "method": "Exact PDF vector/raster extraction via pdftocairo; logical wrappers added without geometry changes.",
  "reference_character": "강철수",
  "notes": [
    "Reference text remains outlined paths for pixel-faithful baseline. Replace/hide data-slot groups for variable values.",
    "No new information fields added.",
    "Name and corner-role design presets for 1-5 characters are embedded as hidden reference groups.",
    "Three controlled presets are provided for 3-character names; role presets are fixed by character count."
  ],
  "template_revision": "variable-v3.0",
  "faction_logo_source": "user-provided transparent emblem",
  "logo_linkage": "Central faint watermark and lower-right primary emblem use the same supplied logo geometry.",
  "background_color_slot": {
    "element": "faction-background-color",
    "default_opacity": 0,
    "note": "Exact PDF background remains baseline. Set fill/opacity on the color-wash layer for faction recoloring."
  },
  "text_mode": {
    "reference_paths": "visible by default for pixel-faithful design reference",
    "editable_svg_text_slots": "present and hidden by default"
  },
  "layout_strategy": {
    "display_name": {
      "char_count_supported": [1,2,3,4,5],
      "three_char_presets": ["A","B","C"],
      "selection_note": "Use a simple stable hash of the name text for 3-character names if automation is desired."
    },
    "corner_role": {
      "char_count_supported": [1,2,3,4,5],
      "preset_count_per_length": 1
    }
  }
}
